package com.jadhavr.erp.fee.controller;
import com.jadhavr.erp.admission.repository.AdmissionFormRepository; import com.jadhavr.erp.college.repository.CollegeRepository; import com.jadhavr.erp.common.api.ApiResponse; import com.jadhavr.erp.fee.entity.*; import com.jadhavr.erp.fee.enums.*; import com.jadhavr.erp.fee.repository.*; import com.jadhavr.erp.staff.repository.StaffProfileRepository; import com.jadhavr.erp.student.repository.StudentProfileRepository; import com.jadhavr.erp.user.entity.RoleName; import com.jadhavr.erp.user.repository.UserRepository; import org.springframework.web.bind.annotation.*; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*;
@Transactional(readOnly=true)
@RestController @RequestMapping("/api/super-admin") public class SuperAdminFeeAnalyticsController {private final StudentFeeAccountRepository accounts;private final FeePaymentRepository payments;private final CollegeRepository colleges;private final UserRepository users;private final StaffProfileRepository staff;private final StudentProfileRepository students;private final AdmissionFormRepository admissions;public SuperAdminFeeAnalyticsController(StudentFeeAccountRepository a,FeePaymentRepository p,CollegeRepository c,UserRepository u,StaffProfileRepository sf,StudentProfileRepository st,AdmissionFormRepository ad){accounts=a;payments=p;colleges=c;users=u;staff=sf;students=st;admissions=ad;}
 @GetMapping("/fees/collection-summary")public ApiResponse<?>collectionSummary(){return ApiResponse.success("Collection summary",summary());}@GetMapping("/fees/pending-summary")public ApiResponse<?>pendingSummary(){return ApiResponse.success("Pending summary",Map.of("totalPendingFee",sumPending(),"pendingStudents",accounts.findAll().stream().filter(x->x.getRemainingAmount().signum()>0).count()));}
 @GetMapping("/fees/collections")public ApiResponse<?>collections(@RequestParam(required=false)Long collegeId,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)String academicYear,@RequestParam(required=false)StudentCategory studentCategory){var rows=payments.findAll().stream().filter(x->x.getStatus()==PaymentStatus.VERIFIED).filter(x->collegeId==null||x.getCollege().getId().equals(collegeId)).filter(x->departmentId==null||x.getDepartment().getId().equals(departmentId)).filter(x->academicYear==null||x.getStudentFeeAccount().getAcademicYear().equals(academicYear)).filter(x->studentCategory==null||x.getStudentFeeAccount().getFeeStructure().getStudentCategory()==studentCategory).map(x->Map.of("id",x.getId(),"studentName",x.getStudent().getFullName(),"collegeName",x.getCollege().getName(),"departmentName",x.getDepartment().getName(),"studentCategory",x.getStudentFeeAccount().getFeeStructure().getStudentCategory(),"amount",x.getAmount(),"paymentDate",x.getPaymentDate(),"transactionReference",x.getTransactionReference())).toList();return ApiResponse.success("Fee collections",rows);}
 @GetMapping("/fees/pending")public ApiResponse<?>pending(@RequestParam(required=false)Long collegeId,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)String academicYear,@RequestParam(required=false)StudentCategory studentCategory){var rows=accounts.findAll().stream().filter(x->x.getRemainingAmount().signum()>0).filter(x->collegeId==null||x.getCollege().getId().equals(collegeId)).filter(x->departmentId==null||x.getDepartment().getId().equals(departmentId)).filter(x->academicYear==null||x.getAcademicYear().equals(academicYear)).filter(x->studentCategory==null||x.getFeeStructure().getStudentCategory()==studentCategory).map(x->Map.of("id",x.getId(),"studentName",x.getStudent().getFullName(),"admissionNumber",x.getStudent().getAdmissionNumber(),"collegeName",x.getCollege().getName(),"departmentName",x.getDepartment().getName(),"studentCategory",x.getFeeStructure().getStudentCategory(),"totalFee",x.getTotalFee(),"paidAmount",x.getPaidAmount(),"remainingAmount",x.getRemainingAmount())).toList();return ApiResponse.success("Pending fees",rows);}
 @GetMapping("/analytics")public ApiResponse<?>analytics(){var collegeStudents=colleges.findAll().stream().map(c->Map.of("label",c.getName(),"value",students.findByCollegeId(c.getId()).size())).toList();var collegeFees=colleges.findAll().stream().map(c->Map.of("label",c.getName(),"value",accounts.findAll().stream().filter(x->x.getCollege().getId().equals(c.getId())).map(StudentFeeAccount::getPaidAmount).reduce(BigDecimal.ZERO,BigDecimal::add))).toList();return ApiResponse.success("Admin analytics",Map.of("summary",summary(),"collegeWiseStudents",collegeStudents,"collegeWiseFeeCollection",collegeFees,"admissionStatusDistribution",admissions.findAll().stream().collect(java.util.stream.Collectors.groupingBy(x->x.getStatus().name(),java.util.stream.Collectors.counting())),"pendingFees",accounts.findAll().stream().filter(x->x.getRemainingAmount().signum()>0).limit(10).map(x->Map.of("student",x.getStudent().getFullName(),"college",x.getCollege().getName(),"remaining",x.getRemainingAmount())).toList()));}
 private Map<String,Object>summary(){long principals=users.findAll().stream().filter(u->u.getRoles().stream().anyMatch(r->r.getName()==RoleName.PRINCIPAL)).count();return Map.of("totalColleges",colleges.count(),"activeColleges",colleges.findAll().stream().filter(c->c.getStatus().name().equals("ACTIVE")).count(),"totalPrincipals",principals,"totalStaff",staff.count(),"totalStudents",students.count(),"totalFeeCollection",accounts.findAll().stream().map(StudentFeeAccount::getPaidAmount).reduce(BigDecimal.ZERO,BigDecimal::add),"pendingFee",sumPending());}private BigDecimal sumPending(){return accounts.findAll().stream().map(StudentFeeAccount::getRemainingAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}}
